'use client';
import type { CSSProperties } from 'react';
import { cx } from '../lib/cx';
import { Icon } from '../lib/icons';
import { Fold, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './voice-orb.css';

/** idle (not started), listening, thinking, speaking (the agent) or ended */
export type VoiceState = 'idle' | 'listening' | 'thinking' | 'speaking' | 'ended';

export interface VoiceOrbProps {
  state: VoiceState;
  /** How loud whoever is talking is, 0 to 1. The orb swells with it. Feed it from your audio, or from a made-up curve */
  level?: number;
  /** Your microphone is off. Listening shows as Muted, and the mute button is pressed */
  muted?: boolean;
  onMutedChange?: (muted: boolean) => void;
  /** Shows "You're muted" with an Unmute button, for when someone talks while muted */
  mutedNotice?: boolean;
  /** What was said last and who said it. Each word fades in as it arrives; a new `id` (or speaker) starts a new line */
  caption?: { speaker: string; text: string; id?: string };
  /** Shown before anything is said, like "Talk to the agent about Pricing v4" */
  hint?: string;
  /** Seconds since the chat started, shown top right */
  elapsed?: number;
  onStart?: () => void;
  onEnd?: () => void;
  /** Start again, from the row that shows once the chat has ended */
  onRestart?: () => void;
  /** The quiet line under "Voice chat ended". Defaults to the length and "Transcript saved" */
  endedDetail?: string;
  labels?: { ready?: string; listening?: string; thinking?: string; speaking?: string; muted?: string; ended?: string; start?: string; end?: string; mute?: string; unmute?: string; mutedNotice?: string; endedTitle?: string; restart?: string };
  className?: string;
}

const fmt = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s) % 60).padStart(2, '0')}`;

/** A hands-free voice chat: an orb that swells with whoever is talking, the accent colour for you and violet for the agent, what was
    said under it, and mute and end below. It draws what you pass; it never opens the microphone itself. */
export function VoiceOrb({
  state, level = 0, muted = false, onMutedChange, mutedNotice = false, caption, hint, elapsed = 0, onStart, onEnd, onRestart, endedDetail, labels = {}, className
}: VoiceOrbProps) {
  const L = { ready: 'Ready', listening: 'Listening', thinking: 'Thinking', speaking: 'Speaking', muted: 'Muted', ended: 'Ended', start: 'Start talking', end: 'End', mute: 'Mute', unmute: 'Unmute', mutedNotice: "You're muted. Unmute so the agent can hear you.", endedTitle: 'Voice chat ended', restart: 'Start again', ...labels };
  // muted only changes how listening looks: the agent can still think and speak
  const m = muted && state === 'listening' ? 'muted' : state;
  const status = { idle: L.ready, listening: L.listening, thinking: L.thinking, speaking: L.speaking, muted: L.muted, ended: L.ended }[m];
  const on = state !== 'idle' && state !== 'ended';

  return (
    <div data-dm="" className={className} style={{ width: '100%' }}>
      <div className={cx('dm-vor dm-panel', on && 'dm-on')} data-m={m}>
        <div className="dm-vor-top"><span className="dm-vor-dot" /><Swap className="dm-vor-st">{status}</Swap><span className="dm-vor-t dm-num dm-muted">{fmt(elapsed)}</span></div>
        <div className="dm-vor-orb" aria-hidden="true" style={{ '--dm-lv': Math.max(0, Math.min(1, level)).toFixed(3) } as CSSProperties}><i className="dm-vor-glow" /><i className="dm-vor-core" /></div>
        <div className="dm-vor-cap" aria-live="polite">
          <Swap className="dm-vor-who dm-muted">{caption?.speaker ?? ''}</Swap>
          {caption
            ? <p className="dm-vor-tx" key={caption.id ?? caption.speaker}>{caption.text.split(' ').filter(Boolean).map((w, i) => <span key={i} className="dm-w">{w} </span>)}</p>
            : <p className="dm-vor-tx dm-hint">{hint}</p>}
        </div>
        <Fold open={mutedNotice && muted && on} className="dm-vor-mf">
          <div className="dm-vor-mw"><p><Icon name="alert" size="xs" /><span>{L.mutedNotice}</span></p><button type="button" className="dm-pill dm-sm" onClick={() => onMutedChange?.(false)}>{L.unmute}</button></div>
        </Fold>
        {state === 'ended' ? (
          <div className="dm-vor-done dm-enter">
            <Icon name="ok" />
            <span className="dm-t">{L.endedTitle}<span className="dm-muted">{endedDetail ?? `${fmt(elapsed)} · Transcript saved`}</span></span>
            {onRestart && <button type="button" className="dm-pill dm-sm" onClick={onRestart}>{L.restart}</button>}
          </div>
        ) : (
          <div className="dm-vor-f">
            <button type="button" className="dm-pill dm-ink dm-sm dm-vor-go" onClick={onStart}><Icon name="mic" size="xs" />{L.start}</button>
            <Tip label={muted ? L.unmute : L.mute}><button type="button" className="dm-ib dm-fill dm-vor-mute" aria-label={L.mute} aria-pressed={muted} onClick={() => onMutedChange?.(!muted)}><Icon name="mic" /></button></Tip>
            <span className="dm-sp" />
            <button type="button" className="dm-pill dm-sm dm-vor-end" onClick={onEnd}>{L.end}</button>
          </div>
        )}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Voice orb ---------- */
/* a hands-free voice chat: an orb that swells with whoever is talking, the accent colour for you and violet for the agent, what
   was said under it, and mute and end below. Talking while muted says so, the way calls do */
.dm-vor{position:relative;width:100%;max-width:380px;margin:0 auto;padding:16px;display:flex;flex-direction:column;gap:12px;--dm-oc:var(--dm-faint)}
.dm-vor[data-m="listening"]{--dm-oc:var(--dm-accent)}
.dm-vor[data-m="speaking"]{--dm-oc:var(--dm-pl)}
.dm-vor[data-m="thinking"]{--dm-oc:color-mix(in srgb,var(--dm-accent) 50%,var(--dm-pl))}
.dm-vor[data-m="muted"]{--dm-oc:color-mix(in srgb,var(--dm-muted) 55%,var(--dm-faint))}
.dm-vor-top{display:flex;align-items:center;gap:8px;font-size:13px}
.dm-vor-dot{width:8px;height:8px;border-radius:50%;background:var(--dm-oc);transition:background .4s}
.dm-vor[data-m="listening"] .dm-vor-dot,.dm-vor[data-m="speaking"] .dm-vor-dot{animation:dm-vor-pulse 1.4s var(--dm-ease-io) infinite}
@keyframes dm-vor-pulse{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-oc) 35%,transparent)}50%{box-shadow:0 0 0 5px transparent}}
.dm-vor-t{margin-left:auto;font-size:12.5px}
.dm-vor-orb{position:relative;width:112px;height:112px;margin:8px auto;--dm-lv:0}
.dm-vor-orb i{position:absolute;inset:0;border-radius:50%}
/* round in Blueprint too, where every other corner is square: like the turning loaders, its shape is what it says */
.dm-vor .dm-vor-orb i{border-radius:50%!important}
.dm-vor-glow{background:radial-gradient(closest-side,color-mix(in srgb,var(--dm-oc) 28%,transparent),transparent);transform:scale(calc(1.1 + var(--dm-lv) * .45))}
.dm-vor-core{background-color:color-mix(in srgb,var(--dm-oc) 72%,var(--dm-surface));background-image:radial-gradient(circle at 34% 28%,rgba(255,255,255,.42),rgba(255,255,255,0) 62%);box-shadow:inset 0 -8px 18px color-mix(in srgb,var(--dm-oc) 30%,transparent);transform:scale(calc(.9 + var(--dm-lv) * .14));transition:background-color .4s}
.dm-vor[data-m="thinking"] .dm-vor-core{animation:dm-vor-br 1.6s var(--dm-ease-io) infinite alternate}
@keyframes dm-vor-br{from{transform:scale(.9)}to{transform:scale(.96)}}
.dm-vor-cap{min-height:88px;display:flex;flex-direction:column;gap:2px;text-align:center}
.dm-vor-who{font-size:12px;min-height:18px}
.dm-vor-tx{margin:0;font-size:14px;line-height:1.6;color:var(--dm-fg)}
.dm-vor-tx.dm-hint{color:var(--dm-muted);font-size:13px}
.dm-vor-tx .dm-w{animation:dm-vor-w .45s var(--dm-ease) both}
@keyframes dm-vor-w{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.dm-vor-mw{display:flex;align-items:center;gap:10px;padding:8px 8px 8px 12px;border-radius:12px;background:var(--dm-warn-bg)}
.dm-vor-mw p{margin:0;flex:1;display:flex;gap:8px;font-size:13px;line-height:1.45;color:var(--dm-fg)}
.dm-vor-mw p svg{color:var(--dm-warn);flex:none;margin-top:3px}
.dm-vor-mw .dm-pill,.dm-vor-done .dm-pill{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
.dm-vor-f{display:flex;align-items:center;gap:8px;min-height:32px}
.dm-vor-f .dm-sp{flex:1}
.dm-vor:not(.dm-on) .dm-vor-f{justify-content:center}
.dm-vor:not(.dm-on) .dm-vor-mute,.dm-vor:not(.dm-on) .dm-vor-end,.dm-vor:not(.dm-on) .dm-vor-f .dm-sp,.dm-vor.dm-on .dm-vor-go{display:none}
.dm-vor-mute{position:relative}
.dm-vor-mute[aria-pressed="true"]{background:var(--dm-bad-bg);color:var(--dm-bad);box-shadow:none}
/* the slash across the microphone once it is muted */
.dm-vor-mute::after{content:"";position:absolute;left:50%;top:50%;width:1.5px;height:18px;margin:-9px 0 0 -.75px;border-radius:2px;background:currentColor;transform:rotate(-45deg) scaleY(0);transition:transform .25s var(--dm-ease)}
.dm-vor-mute[aria-pressed="true"]::after{transform:rotate(-45deg) scaleY(1)}
.dm-vor-end{background:var(--dm-bad);color:#fff}
.dm-vor-end:hover{background:color-mix(in srgb,var(--dm-bad) 86%,#000)}
.dm-vor-done{display:flex;align-items:center;gap:12px;padding:10px 10px 10px 12px;border-radius:12px;background:var(--dm-chip);font-size:13.5px}
.dm-vor-done>svg{color:var(--dm-fg2);flex:none}
.dm-vor-done .dm-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-vor-done .dm-t span{font-size:13px}

